import java.util.function.Predicate;

public class Demo {
    public static void main(String[] args) {
        Predicate<Integer> isGreater = x -> x > 100;
        Predicate<Integer> isEven = x -> x % 2 == 0;

        System.out.println(isGreater.and(isEven).test(56));
        System.out.println(isGreater.or(isEven).negate().test(57));
    }
}

import java.util.function.Function;

public class Demo3 {
    public static void main(String[] args) {
        Function<Integer, Integer> add2 = x -> x + 2;
        Function<Integer, Integer> multiply3 = x -> x * 3;

        System.out.println(add2.andThen(multiply3).apply(4));
        System.out.println(add2.compose(multiply3).apply(4));
    }
}

import java.util.function.Function;

public class Compose {
    public static void main(String[] args) {
        Function<Integer, String> f = x -> "v" + x;
        Function<String, Integer> g = String::length;

        Function<Integer, Integer> a = f.andThen(g);   // Line A
        Function<String, String>   b = g.andThen(f);   // Line B
        Function<String, String>   c = f.compose(g);   // Line C
        Function<Integer, Integer> d = f.compose(g);   // Line D
    }
}
